package com.tietsync.security;
import jakarta.servlet.FilterChain; import jakarta.servlet.ServletException; import jakarta.servlet.http.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.context.annotation.*; import org.springframework.http.HttpMethod; import org.springframework.security.authentication.*; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.config.annotation.web.configuration.EnableWebSecurity; import org.springframework.security.config.http.SessionCreationPolicy; import org.springframework.security.core.*; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.security.web.*; import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter; import org.springframework.stereotype.Component; import org.springframework.web.cors.*; import org.springframework.web.filter.OncePerRequestFilter; import io.jsonwebtoken.*; import io.jsonwebtoken.security.Keys; import java.io.IOException; import java.nio.charset.StandardCharsets; import java.time.*; import java.util.*;
@Configuration @EnableWebSecurity class SecurityConfig {
 @Bean PasswordEncoder passwordEncoder(){return new BCryptPasswordEncoder();}
 @Bean SecurityFilterChain filterChain(HttpSecurity http, JwtFilter jwt) throws Exception { return http.csrf(c->c.disable()).cors(c->{}).sessionManagement(s->s.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).authorizeHttpRequests(a->a.requestMatchers("/actuator/**","/swagger-ui/**","/v3/api-docs/**","/api/v1/auth/**").permitAll().requestMatchers(HttpMethod.GET,"/api/v1/classrooms/**","/api/v1/faculty/**","/api/v1/resources/**","/api/v1/calendar/**").permitAll().anyRequest().authenticated()).addFilterBefore(jwt,UsernamePasswordAuthenticationFilter.class).build(); }
 @Bean CorsConfigurationSource cors(@Value("${app.frontend-url}") String frontend){ CorsConfiguration c=new CorsConfiguration(); c.setAllowedOrigins(Arrays.asList(frontend,"http://localhost:5173")); c.setAllowedMethods(List.of("GET","POST","PUT","PATCH","DELETE","OPTIONS")); c.setAllowedHeaders(List.of("Authorization","Content-Type")); c.setAllowCredentials(true); UrlBasedCorsConfigurationSource s=new UrlBasedCorsConfigurationSource();s.registerCorsConfiguration("/**",c);return s; }
}
@Component class JwtFilter extends OncePerRequestFilter { private final JwtService jwt; JwtFilter(JwtService jwt){this.jwt=jwt;} @Override protected void doFilterInternal(HttpServletRequest r,HttpServletResponse s,FilterChain c)throws ServletException,IOException {String h=r.getHeader("Authorization");if(h!=null&&h.startsWith("Bearer "))try{Claims x=jwt.parse(h.substring(7));var a=new UsernamePasswordAuthenticationToken(x.getSubject(),null,List.of(new SimpleGrantedAuthority("ROLE_"+x.get("role",String.class))));SecurityContextHolder.getContext().setAuthentication(a);}catch(JwtException ignored){}c.doFilter(r,s);} }
